(function () {
  "use strict";

  window.tildafontsswap = "y";
  window.tildafonts_loaded = false;

  var fonts = Array.isArray(window.TildaFonts) ? window.TildaFonts : [];
  if (!fonts.length) {
    window.tildafonts_loaded = true;
    return;
  }

  var head = document.head || document.getElementsByTagName("head")[0];
  var query = "?fonts=" + encodeURIComponent(fonts.join(",")) + "&format=woff2&display=swap";

  function loadFontStylesheet(origin, allowFallback) {
    var link = document.createElement("link");
    link.rel = "stylesheet";
    link.type = "text/css";
    link.media = "all";
    link.href = origin + query;
    link.addEventListener("load", function () {
      window.tildafonts_loaded = true;
    });
    link.addEventListener("error", function () {
      if (allowFallback) {
        loadFontStylesheet("https://fonts2.tildacdn.com/get/", false);
      }
    });
    head.insertBefore(link, head.firstChild);
  }

  loadFontStylesheet("https://fonts.tildacdn.com/get/", true);
})();

